import{_ as l,a0 as r,w as o,s as p,ao as h,I as n,x as i,a1 as a,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在任何地方使用 Vim 编辑器输入文本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在任何地方使用 Vim 编辑器输入文本 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在任何地方使用 Vim 编辑器输入文本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在任何地方使用 Vim 编辑器输入文本 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180501 How To Use Vim Editor To Input Text Anywhere","title":"如何在任何地方使用 Vim 编辑器输入文本","tag":"201805","desc":""},"relativePath":"201805/20180501 How To Use Vim Editor To Input Text Anywhere.md","filePath":"[post].md"}'),d={name:"201805/20180501 How To Use Vim Editor To Input Text Anywhere.md"};function m(g,e,u,c,k,w){const t=r("Link");return o(),p("div",null,[e[15]||(e[15]=h('<h1 id="如何在任何地方使用-vim-编辑器输入文本" tabindex="-1">如何在任何地方使用 Vim 编辑器输入文本 <a class="header-anchor" href="#如何在任何地方使用-vim-编辑器输入文本" aria-label="Permalink to “如何在任何地方使用 Vim 编辑器输入文本”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/vim-anywhere-720x340.png" alt=""></p><p>各位 Vim 使用者大家好！今天，我这里有个好消息告诉大家。我会向大家介绍 <strong>Vim-anywhere</strong>，这是一个简单的脚本，它允许你使用 Vim 编辑器在 Linux 中的任何地方输入文本。这意味着你能简单地调用自己最爱的 Vim 编辑器，输入任何你所想的，并将这些文本粘贴到任意的应用和网站中。这些文本将在剪贴板可用，直到你重启了系统。这个工具对那些喜欢在非 Vim 环境中使用 Vim 键位绑定的人来说十分有用。</p><h3 id="在-linux-中安装-vim-anywhere" tabindex="-1">在 Linux 中安装 Vim-anywhere <a class="header-anchor" href="#在-linux-中安装-vim-anywhere" aria-label="Permalink to “在 Linux 中安装 Vim-anywhere”">​</a></h3><p>Vim-anywhere 工具可以运行在任何基于 GNOME（或其他衍生品）的 Linux 发行版上。另外，确保你已经安装了下面的依赖。</p><ul><li>Curl</li><li>Git</li><li>gVim</li><li>xclip</li></ul><p>比如，你可以用下面的命令在 Ubuntu 中安装这些工具：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install curl git vim-gnome xclip</span></span></code></pre></div><p>然后运行如下的命令来安装 Vim-anywhere：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL https://raw.github.com/cknadler/vim-anywhere/master/install | bash</span></span></code></pre></div><p>Vim-anywhere 到此已经安装完成。现在我们来看看如何使用它。</p><h3 id="在任何地方使用-vim-编辑器输入文本" tabindex="-1">在任何地方使用 Vim 编辑器输入文本 <a class="header-anchor" href="#在任何地方使用-vim-编辑器输入文本" aria-label="Permalink to “在任何地方使用 Vim 编辑器输入文本”">​</a></h3><p>假如你需要创建一个 word 文档。但是你更愿意使用 Vim 编辑器，而不是 LibreOffice。没问题，这里 Vim-anywhere 就派上用场了。Vim-anywhere 自动化了整个流程。它仅仅简单地调用 Vim 编辑器，所以你能写任何你所想的，然后将之粘贴到 .doc 文件中。</p><p>让我给你展示一个用例。打开 LibreOffice 或者你选的任何图形文本编辑器。然后打开 Vim-anywhere。你只需要按下 <code>CTRL+ALT+V</code> 即可。它将会打开 gVim 编辑器。按下 <code>i</code> 切换到交互模式然后输入文本。完成之后，键入 <code>:wq</code> 关闭并保存文件。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/vim-anywhere-1-1.png" alt=""></p><p>这些文本会在剪贴板中可用，直到你重启了系统。在你关闭编辑器之后，你之前的应用会重新占据主界面。你只需按下 <code>CTRL+P</code> 将文本粘贴进去。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/vim-anywhere-2.png" alt=""></p><p>这仅仅只是一个例子。你甚至可以使用 Vim-anywhere 在烦人的 web 表单或者其他应用上进行输入。一旦 Vim-anywhere 被调用，它将会打开一个缓冲区。关闭 Vim-anywhere 之后，缓冲器内的内容会自动复制到你的剪贴板中，之前的应用会重新占据主界面。</p><p>Vim-anywhere 在被调用的时候会在 <code>/tmp/vim-anywhere</code> 中创建一个临时文件。这些临时文件会一致保存着，直到你重启了系统，并为你提供临时的历史记录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /tmp/vim-anywhere</span></span></code></pre></div><p>你可以用下面的命令重新打开最近的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim $( ls /tmp/vim-anywhere | sort -r | head -n 1 )</span></span></code></pre></div><h4 id="更新-vim-anywhere" tabindex="-1">更新 Vim-anywhere <a class="header-anchor" href="#更新-vim-anywhere" aria-label="Permalink to “更新 Vim-anywhere”">​</a></h4><p>运行下面的命令来更新 Vim-anywhere：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ~/.vim-anywhere/update</span></span></code></pre></div><h4 id="更改快捷键" tabindex="-1">更改快捷键 <a class="header-anchor" href="#更改快捷键" aria-label="Permalink to “更改快捷键”">​</a></h4><p>默认调用 Vim-anywhere 的键位是 <code>CTRL+ALT+V</code>。你可以用 <code>gconf</code> 工具将其更改为任何自定义的键位绑定。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gconftool -t str --set /desktop/gnome/keybindings/vim-anywhere/binding &lt;custom binding&gt;</span></span></code></pre></div><h4 id="卸载-vim-anywhere" tabindex="-1">卸载 Vim-anywhere <a class="header-anchor" href="#卸载-vim-anywhere" aria-label="Permalink to “卸载 Vim-anywhere”">​</a></h4><p>可能有些人觉得每次打开 Vim 编辑器，输入一些文本，然后将文本复制到其他应用中是没有意义也毫无必要的。</p><p>如果你不觉得这个工具有用，只需使用下面的命令来卸载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ~/.vim-anywhere/uninstall</span></span></code></pre></div><hr>',33)),n("p",null,[e[1]||(e[1]=i("via: ",-1)),a(t,{href:"https://www.ostechnix.com/how-to-use-vim-editor-to-input-text-anywhere/"},{default:s(()=>[...e[0]||(e[0]=[i("https://www.ostechnix.com/how-to-use-vim-editor-to-input-text-anywhere/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=i("作者：",-1)),a(t,{href:"https://www.ostechnix.com/author/sk/"},{default:s(()=>[...e[2]||(e[2]=[i("SK",-1)])]),_:1}),e[7]||(e[7]=i(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[3]||(e[3]=[i("lujun9972",-1)])]),_:1}),e[8]||(e[8]=i(" 译者：",-1)),a(t,{href:"https://github.com/paperzhang"},{default:s(()=>[...e[4]||(e[4]=[i("paperzhang",-1)])]),_:1}),e[9]||(e[9]=i(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[5]||(e[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[10]||(e[10]=[i("LCTT",-1)])]),_:1}),e[13]||(e[13]=i(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:s(()=>[...e[11]||(e[11]=[i("Linux中国",-1)])]),_:1}),e[14]||(e[14]=i(" 荣誉推出",-1))])])}const V=l(d,[["render",m]]);export{f as __pageData,V as default};
